//! Fee and interest audit — what the accounts are charging, gathered into one place.
//!
//! Fees are invisible for a structural reason: each one is small and they are scattered across
//! months and accounts. Nobody adds them up, so nobody sees the total, so nobody acts. Listing them
//! together turns a statement into a CALL SHEET — many are reversible on request, and a repeating fee
//! is usually a standing condition (a plan, a threshold, a due date) that can be changed once.
//!
//! # Patterns are data
//!
//! Institutions word these differently and change the wording; a matcher hard-coded into the logic
//! would silently stop matching and report a clean bill of health, which is the worst possible
//! failure for an audit. So the patterns are a TABLE, correctable in one line, and anything that
//! looks fee-shaped but matches nothing is REPORTED as unclassified rather than dropped.
use crate::money::{money, sum, Currency, Money};
use crate::txn::{month_of, Txn};

/// What kind of charge this is. The kinds differ in WHAT YOU CAN DO ABOUT THEM, which is the point.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FeeKind {
    Interest,
    Late,
    Overdraft,
    Nsf,
    Annual,
    ForeignTransaction,
    CashAdvance,
    Service,
}

impl FeeKind {
    pub fn label(self) -> &'static str {
        match self {
            FeeKind::Interest => "interest",
            FeeKind::Late => "late",
            FeeKind::Overdraft => "overdraft",
            FeeKind::Nsf => "nsf",
            FeeKind::Annual => "annual",
            FeeKind::ForeignTransaction => "foreign-transaction",
            FeeKind::CashAdvance => "cash-advance",
            FeeKind::Service => "service",
        }
    }
}

/// One alternative in a pattern.
///
/// The TypeScript uses regular expressions; every one of them reduces to a case-insensitive
/// alternation of literals plus a SINGLE wildcard construct (`non.?sufficient`). Two variants cover
/// the whole table, which is cheaper than a regex dependency and — more importantly — cannot quietly
/// acquire behaviour nobody wrote down.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Alt {
    /// A plain case-insensitive substring. Deliberately NOT word-bounded, matching the TypeScript:
    /// `od fee` finds "GOOD FEE" in both kits, and a change here would be a silent divergence.
    Literal(&'static str),
    /// `prefix` then AT MOST ONE character then `suffix` — the regex `non.?sufficient`, which is how
    /// "nonsufficient", "non-sufficient" and "non sufficient" are all one rule.
    Gap(&'static str, &'static str),
}

#[derive(Debug, Clone, Copy)]
pub struct FeePattern {
    pub kind: FeeKind,
    pub alts: &'static [Alt],
    /// What can actually be DONE about it. The reason the kinds are separate at all.
    pub lever: &'static str,
}

pub const FEE_PATTERNS: &[FeePattern] = &[
    FeePattern {
        kind: FeeKind::Interest,
        alts: &[Alt::Literal("interest charge"), Alt::Literal("finance charge"), Alt::Literal("purchase interest"), Alt::Literal("int chg")],
        lever: "a rate reduction, or clearing the balance faster — this is the recurring cost of the balance itself",
    },
    FeePattern {
        kind: FeeKind::Late,
        alts: &[Alt::Literal("late fee"), Alt::Literal("late charge"), Alt::Literal("past due fee")],
        lever: "usually reversible on request, especially once; a due-date change prevents the next one",
    },
    FeePattern {
        kind: FeeKind::Overdraft,
        alts: &[Alt::Literal("overdraft"), Alt::Literal("od fee"), Alt::Literal("odp fee")],
        lever: "often reversible; overdraft coverage can be switched off, or a buffer account linked",
    },
    FeePattern {
        kind: FeeKind::Nsf,
        alts: &[Alt::Literal("nsf"), Alt::Gap("non", "sufficient"), Alt::Literal("returned item"), Alt::Literal("insufficient funds")],
        lever: "often reversible once; the underlying cause is timing rather than total",
    },
    FeePattern {
        kind: FeeKind::Annual,
        alts: &[Alt::Literal("annual fee"), Alt::Literal("membership fee"), Alt::Literal("card fee")],
        lever: "ask for it to be waived, or move to a no-fee product on the same account",
    },
    FeePattern {
        kind: FeeKind::ForeignTransaction,
        // `intl? fee` is exactly these two literals.
        alts: &[Alt::Literal("foreign transaction"), Alt::Literal("foreign purchase"), Alt::Literal("int fee"), Alt::Literal("intl fee")],
        lever: "structural — a no-foreign-fee card avoids it entirely",
    },
    FeePattern {
        kind: FeeKind::CashAdvance,
        alts: &[Alt::Literal("cash advance"), Alt::Literal("cash adv fee")],
        lever: "no grace period and a higher rate; the fix is not using the facility",
    },
    FeePattern {
        kind: FeeKind::Service,
        alts: &[Alt::Literal("service charge"), Alt::Literal("maintenance fee"), Alt::Literal("monthly fee"), Alt::Literal("paper statement")],
        lever: "usually waived by a balance minimum, a direct deposit, or switching statement delivery",
    },
];

/// Words that mark a line as fee-shaped even when no specific pattern matches it.
///
/// WORD-BOUNDED, unlike the pattern literals: `\bfee\b` must not find "coffee", or every café would
/// enter the audit as an unclassified charge and the gap-in-the-table signal would be noise.
const FEE_SHAPED: &[&str] = &["fee", "charge", "interest", "penalty"];

fn is_word_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// `\bword\b` over an already-lowercased haystack.
fn contains_word(text: &str, word: &str) -> bool {
    let b = text.as_bytes();
    let mut from = 0;
    while let Some(i) = text[from..].find(word).map(|i| i + from) {
        let before_ok = i == 0 || !is_word_char(b[i - 1] as char);
        let end = i + word.len();
        let after_ok = end >= b.len() || !is_word_char(b[end] as char);
        if before_ok && after_ok {
            return true;
        }
        from = i + 1;
    }
    false
}

fn alt_matches(text: &str, alt: &Alt) -> bool {
    match alt {
        Alt::Literal(s) => text.contains(s),
        Alt::Gap(prefix, suffix) => {
            let mut from = 0;
            while let Some(i) = text[from..].find(prefix).map(|i| i + from) {
                let after = i + prefix.len();
                // AT MOST ONE character between, matching `.?` — and `.` never matches a newline in
                // a JavaScript regex, so a line break does not bridge the gap here either.
                for skip in [0usize, 1] {
                    let start = after + skip;
                    if skip == 1 {
                        match text[after..].chars().next() {
                            None | Some('\n') => continue,
                            Some(_) => {}
                        }
                    }
                    if text.is_char_boundary(start) && text[start..].starts_with(suffix) {
                        return true;
                    }
                }
                from = i + 1;
            }
            false
        }
    }
}

/// Which pattern a description falls under. FIRST MATCH WINS, so the table order is meaningful.
pub fn classify(description: &str) -> Option<&'static FeePattern> {
    let text = description.to_lowercase();
    FEE_PATTERNS.iter().find(|p| p.alts.iter().any(|a| alt_matches(&text, a)))
}

/// Fee-shaped but unmatched — a gap in the table, visible as a gap.
pub fn looks_fee_shaped(description: &str) -> bool {
    let text = description.to_lowercase();
    FEE_SHAPED.iter().any(|w| contains_word(&text, w))
}

#[derive(Debug, Clone, PartialEq)]
pub struct Fee {
    pub date: String,
    pub account: String,
    pub description: String,
    pub amount: Money,
    pub kind: FeeKind,
    pub lever: &'static str,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RecurringCondition {
    pub account: String,
    pub kind: FeeKind,
    pub months: usize,
    pub total: Money,
    pub lever: &'static str,
}

#[derive(Debug, Clone, PartialEq)]
pub struct FeeAudit {
    pub fees: Vec<Fee>,
    /// Total charged over the whole set. The number nobody has ever seen before running this.
    pub total: Money,
    pub by_kind: Vec<(FeeKind, Money)>,
    pub by_account: Vec<(String, Money)>,
    /// A kind that appears in THREE OR MORE distinct months on one account: not an accident, a
    /// standing condition. These are where a single change stops a stream of charges.
    pub recurring_conditions: Vec<RecurringCondition>,
    /// Looked fee-shaped, matched no pattern. REPORTED so a gap in the table is visible as a gap —
    /// an audit that silently matches nothing reports zero fees, which reads like good news.
    pub unclassified: Vec<Txn>,
}

pub fn audit_fees(txns: &[Txn], currency: Currency) -> FeeAudit {
    let mut fees: Vec<Fee> = Vec::new();
    let mut unclassified: Vec<Txn> = Vec::new();

    for t in txns {
        // A fee is money LEAVING. A line matching "interest" that pays IN is interest earned, which
        // is a different thing entirely and must not be totalled as a cost.
        if t.amount.minor >= 0 {
            continue;
        }
        match classify(&t.description) {
            Some(p) => fees.push(Fee {
                date: t.date.clone(),
                account: t.account.clone(),
                description: t.description.clone(),
                amount: t.amount,
                kind: p.kind,
                lever: p.lever,
            }),
            None if looks_fee_shaped(&t.description) => unclassified.push(t.clone()),
            None => {}
        }
    }

    let mut by_kind: Vec<(FeeKind, Money)> = Vec::new();
    let mut by_account: Vec<(String, Money)> = Vec::new();
    for f in &fees {
        match by_kind.iter_mut().find(|(k, _)| *k == f.kind) {
            Some((_, v)) => *v = money(v.minor + f.amount.minor, currency),
            None => by_kind.push((f.kind, money(f.amount.minor, currency))),
        }
        match by_account.iter_mut().find(|(a, _)| *a == f.account) {
            Some((_, v)) => *v = money(v.minor + f.amount.minor, currency),
            None => by_account.push((f.account.clone(), money(f.amount.minor, currency))),
        }
    }

    // A REPEATING fee is the finding worth acting on: one change stops the whole stream. Keyed on
    // the `(account, kind)` PAIR, as every other grouping here is.
    struct Group {
        account: String,
        kind: FeeKind,
        months: Vec<String>,
        total: i64,
        lever: &'static str,
    }
    let mut groups: Vec<Group> = Vec::new();
    for f in &fees {
        let m = month_of(&f.date).to_string();
        match groups.iter_mut().find(|g| g.account == f.account && g.kind == f.kind) {
            Some(g) => {
                if !g.months.contains(&m) {
                    g.months.push(m);
                }
                g.total += f.amount.minor;
                g.lever = f.lever;
            }
            None => groups.push(Group { account: f.account.clone(), kind: f.kind, months: vec![m], total: f.amount.minor, lever: f.lever }),
        }
    }
    let mut recurring_conditions: Vec<RecurringCondition> = groups
        .into_iter()
        .filter(|g| g.months.len() >= 3)
        .map(|g| RecurringCondition { account: g.account, kind: g.kind, months: g.months.len(), total: money(g.total, currency), lever: g.lever })
        .collect();
    // COSTLIEST STANDING CONDITION FIRST — and since a fee is a negative amount, ascending order is
    // what puts the biggest one at the top. Sorting descending here would silently invert the list.
    recurring_conditions.sort_by_key(|r| r.total.minor);

    let amounts: Vec<Money> = fees.iter().map(|f| f.amount).collect();
    let total = sum(&amounts, currency).unwrap_or_else(|_| money(0, currency));

    FeeAudit { fees, total, by_kind, by_account, recurring_conditions, unclassified }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn t(date: &str, description: &str, minor: i64, account: &str) -> Txn {
        Txn { account: account.to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn kind_of(description: &str) -> Option<&'static str> {
        classify(description).map(|p| p.kind.label())
    }

    #[test]
    fn every_wording_in_the_table_lands_on_its_kind() {
        // Measured by running finance-fees.ts on each of these descriptions.
        for (d, want) in [
            ("INTEREST CHARGE ON PURCHASES", "interest"),
            ("FINANCE CHARGE", "interest"),
            ("INT CHG", "interest"),
            ("LATE FEE", "late"),
            ("PAST DUE FEE", "late"),
            ("OVERDRAFT FEE", "overdraft"),
            ("OD FEE", "overdraft"),
            ("NSF FEE", "nsf"),
            ("RETURNED ITEM", "nsf"),
            ("ANNUAL FEE", "annual"),
            ("MEMBERSHIP FEE", "annual"),
            ("FOREIGN TRANSACTION FEE", "foreign-transaction"),
            ("INT FEE", "foreign-transaction"),
            ("INTL FEE", "foreign-transaction"),
            ("CASH ADVANCE FEE", "cash-advance"),
            ("SERVICE CHARGE", "service"),
            ("MONTHLY FEE", "service"),
            ("PAPER STATEMENT", "service"),
        ] {
            assert_eq!(kind_of(d), Some(want), "{d}");
        }
        assert_eq!(FEE_PATTERNS.len(), 8);
    }

    #[test]
    fn the_one_wildcard_in_the_table_covers_three_spellings_of_the_same_fee() {
        // `non.?sufficient` — at most one character between, which is how all three are one rule.
        assert_eq!(kind_of("NONSUFFICIENT FUNDS"), Some("nsf"));
        assert_eq!(kind_of("NON-SUFFICIENT FUNDS"), Some("nsf"));
        assert_eq!(kind_of("NON SUFFICIENT FUNDS"), Some("nsf"));
        // TWO characters between is not a match — `.?` is at most one.
        assert!(alt_matches("nonsufficient", &Alt::Gap("non", "sufficient")));
        assert!(alt_matches("non-sufficient", &Alt::Gap("non", "sufficient")));
        assert!(!alt_matches("non--sufficient", &Alt::Gap("non", "sufficient")));
        // And a false start is retried rather than abandoned at the first "non".
        assert!(alt_matches("nonesuch and non sufficient", &Alt::Gap("non", "sufficient")));
    }

    #[test]
    fn fee_shaped_is_word_bounded_so_a_cafe_is_not_an_unclassified_charge() {
        // `\bfee\b` must not find "coffee", or every café enters the audit as a gap in the table
        // and the signal becomes noise.
        assert!(!looks_fee_shaped("COFFEE SHOP"));
        assert!(!looks_fee_shaped("FEEDER SUPPLY CO"));
        assert!(looks_fee_shaped("MYSTERY PENALTY"));
        assert!(looks_fee_shaped("SOME CHARGE HERE"));
        assert!(!looks_fee_shaped("TOLL BOOTH"));
        assert!(looks_fee_shaped("a fee"), "at the end of the string is still a boundary");
        assert!(looks_fee_shaped("fee-based"), "a hyphen is a boundary");
        assert!(!looks_fee_shaped("fee_based"), "an underscore is a word character, as in JavaScript");
    }

    #[test]
    fn the_pattern_literals_are_not_word_bounded_and_that_matches_the_other_kit() {
        // `od fee` has no \b in the TypeScript, so it finds "GOOD FEE" there too. Preserved rather
        // than tidied: a divergence here would be invisible and would only show as two kits
        // disagreeing about somebody's statement.
        assert_eq!(kind_of("A GOOD FEE"), Some("overdraft"));
    }

    #[test]
    fn interest_paid_in_is_not_a_fee() {
        // A line matching "interest" that pays in is interest EARNED. Totalling it as a cost would
        // make a savings account look like it was charging you.
        let a = audit_fees(&[t("2026-01-01", "INTEREST PAID", 500, "sav")], Currency::USD);
        assert!(a.fees.is_empty());
        assert!(a.unclassified.is_empty(), "and it is not a gap in the table either");
        assert_eq!(a.total.minor, 0);
    }

    #[test]
    fn the_audit_totals_what_nobody_has_added_up_before() {
        let rows = vec![
            t("2026-01-05", "INTEREST CHARGE ON PURCHASES", -4_500, "visa"),
            t("2026-02-05", "INTEREST CHARGE ON PURCHASES", -4_300, "visa"),
            t("2026-03-05", "INTEREST CHARGE ON PURCHASES", -4_100, "visa"),
            t("2026-01-09", "LATE FEE", -3_500, "visa"),
            t("2026-02-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-03-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-04-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-02-11", "WEIRD PENALTY THING", -900, "chk"),
        ];
        let a = audit_fees(&rows, Currency::USD);
        assert_eq!(a.fees.len(), 7);
        assert_eq!(a.total.minor, -20_000, "$200 nobody had seen as one number");
        assert_eq!(a.by_kind.iter().map(|(k, v)| (k.label(), v.minor)).collect::<Vec<_>>(), vec![("interest", -12_900), ("late", -3_500), ("service", -3_600)]);
        assert_eq!(a.by_account.iter().map(|(k, v)| (k.as_str(), v.minor)).collect::<Vec<_>>(), vec![("visa", -16_400), ("chk", -3_600)]);
        // Fee-shaped and unmatched: REPORTED, so a gap in the table is visible as a gap.
        assert_eq!(a.unclassified.len(), 1);
        assert_eq!(a.unclassified[0].description, "WEIRD PENALTY THING");
    }

    #[test]
    fn three_months_of_the_same_charge_is_a_standing_condition_not_an_accident() {
        let rows = vec![
            t("2026-01-05", "INTEREST CHARGE ON PURCHASES", -4_500, "visa"),
            t("2026-02-05", "INTEREST CHARGE ON PURCHASES", -4_300, "visa"),
            t("2026-03-05", "INTEREST CHARGE ON PURCHASES", -4_100, "visa"),
            t("2026-01-09", "LATE FEE", -3_500, "visa"),
            t("2026-02-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-03-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-04-20", "MONTHLY FEE", -1_200, "chk"),
        ];
        let a = audit_fees(&rows, Currency::USD);
        let got: Vec<(&str, &str, usize, i64)> = a.recurring_conditions.iter().map(|r| (r.account.as_str(), r.kind.label(), r.months, r.total.minor)).collect();
        // COSTLIEST FIRST — and a fee is negative, so that is ASCENDING. The single late fee is one
        // month and is correctly not a standing condition.
        assert_eq!(got, vec![("visa", "interest", 3, -12_900), ("chk", "service", 3, -3_600)]);
        assert!(a.recurring_conditions.iter().all(|r| !r.lever.is_empty()), "each carries what to DO about it");
        assert!(a.recurring_conditions[0].lever.contains("rate reduction"));
    }

    #[test]
    fn two_charges_in_one_month_are_not_three_months() {
        let rows = vec![
            t("2026-01-05", "LATE FEE", -3_500, "visa"),
            t("2026-01-15", "LATE FEE", -3_500, "visa"),
            t("2026-01-25", "LATE FEE", -3_500, "visa"),
        ];
        let a = audit_fees(&rows, Currency::USD);
        assert_eq!(a.fees.len(), 3);
        // DISTINCT months is the test, not occurrences — three in one month is one bad month, and a
        // standing condition is what a single change can stop.
        assert!(a.recurring_conditions.is_empty());
    }

    #[test]
    fn an_empty_set_audits_to_zero_rather_than_failing() {
        let a = audit_fees(&[], Currency::USD);
        assert_eq!(a.total.minor, 0);
        assert!(a.fees.is_empty() && a.by_kind.is_empty() && a.recurring_conditions.is_empty());
    }
}
